llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C71"],
      "claim": "Telmisartan absolute oral bioavailability was 57.4% for a 160 mg tablet versus IV infusion in healthy volunteers, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Safinamide absolute oral bioavailability was 95.0% (range 83.9–119.3%) for a 50 mg IR tablet in fasted subjects versus IV, strongly supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C59"],
      "claim": "Pazopanib absolute oral bioavailability was 21.4% (range 13.5–38.9%) for an 800 mg tablet versus IV in cancer patients, at/above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The supplied numeric absolute oral bioavailability measurements in humans predominantly support F >= 20%, with most values between 35% and 95%; the only sub-20 numeric value is a fed-state rigosertib record, while the corresponding fasting value was 35%.",
  "evidence_gaps": [
    "One rigosertib record in the fed state reports 13.9%, but the fasting absolute value was 35%; the altered feeding condition limits its weight.",
    "Pazopanib has a point estimate of 21.4% with a range crossing below 20%, introducing some threshold-adjacent uncertainty.",
    "Some records are qualitative or lack an absolute bioavailability designation; they were not used as affirmative low-bioavailability evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

